-- 教育部十二年國教英語文領綱 附錄五《參考字彙表（2,000 字）》分級。
--   1 = 表一 基本 1,200 字      2 = 表二 其他常用 800 字
--
-- 跟 0032 的大考中心詞彙表是兩套不同文件：大考那份給高中/學測，這份給國中小/會考。
-- 兩者大量重疊，但這份有 174 個字不在大考表內（cellphone、download 這類生活用字），
-- 只靠 ceec_level 排序永遠輪不到它們。
--
-- 資料來源：https://www.k12ea.gov.tw/ 十二年國教課程綱要 語文領域-英語文（107 年 4 月）
-- 取得方式：官方 PDF → pdftotext -layout → 抓「表一、基本」到「附錄六：」之間，
-- 逐行剝字母標題與頁碼後以逗號切項，括號變體展開（airplane (plane) → airplane, plane；
-- be (am, is, are, was, were, been) → 全收）。展開後 2040 字，在 dict_cache 全部有詞條。
alter table public.dict_cache
  add column if not exists moe_level smallint;

comment on column public.dict_cache.moe_level is
  '教育部國中小參考字彙表：1=基本1200 2=其他常用800，null=不在表內（migration 0033）';

update public.dict_cache d set moe_level = v.lv
